seq_lines = []
with open('region.fasta') as f:
    f.readline()
    for line in f:
        seq_lines.append(line.strip())
seq = ''.join(seq_lines).upper()
N = len(seq)

comp = {'A':'T','T':'A','G':'C','C':'G'}
def revcomp(s): return ''.join(comp[c] for c in reversed(s))

stops = {'TAA','TAG','TGA'}
def scans(strand_seq, strand_name, offset_desc):
    # frame 1 starts at index 0 (position 1)
    for frame in range(3):
        stops_list = []
        for i in range(frame, N-2, 3):
            c = strand_seq[i:i+3]
            if c in stops:
                stops_list.append(i+1)  # 1-based pos of first base of stop
        # gaps between consecutive stops
        prev = None
        for s in stops_list:
            gap = (s - prev) if prev is not None else s
            if gap >= 180:
                print(f'{strand_name} frame {frame+1}: gap of {gap} nt ending at stop pos {s} (prev stop {prev})')
            prev = s
        # handle tail
        tail = (N-1) - stops_list[-1] if stops_list else N
        if tail >= 150:
            print(f'{strand_name} frame {frame+1}: {tail} nt to end after last stop at {stops_list[-1] if stops_list else "none"}')

scans(seq, '+', 'fwd')
scans(revcomp(seq), '-', 'rev')

seq=''.join(l.strip() for l in open('region.fasta').readlines()[1:]).upper()
import re
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[c] for c in reversed(s))
print('— 5′ flank (1-113):', seq[:113])
print('— ORF pickup (114-150):', seq[113:150])
print('— 3′ tail (2855-3000):', seq[2854:])

# Shine-Dalgarno search upstream of ORF start (116): positions 1..115
up = seq[:115]
for m in re.finditer(r'AG.GA|GG.G[GA]|AGGA|GGA|AGG', up):
    d = 115 - (m.start())   # distance from SD start to ORF start+1
    print('SD-like', m.group(0), 'at', m.start()+1, '(≈', d, 'nt upstream of start)')

# -10 box-like TATAAT / -35 TTGACA in first 113 nt
for m in re.finditer(r'TATA[AT]', seq[:115]): print('-10-like:', m.group(0), m.start()+1)
for m in re.finditer(r'TTG.AC|TTG', seq[:115]): print('-35-like:', m.group(0), m.start()+1)

# rho-independent terminator in the 3' tail and rest: GC-rich stem-loop
tail = seq[2854:]
print('\nterminator-like in 3\' tail: searching palindromic 7-11mers...')
for L in range(7,12):
    for i in range(len(tail)-L):
        s = tail[i:i+L]
        if rc(s)==s and s.count('G')+s.count('C')/max(1,L)  > 0 and sum(s.count(c) for c in 'GC')>=L-1:
            print(f' tail pos {2855+i}-{2854+i+L} {s} (GC-rich palindrome)')
